css:
.valuesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2230;
    background: linear-gradient(160deg, #f3f1ea 0%, #ece7da 100%);
    border-radius: 18px;
}

.valuesim-container * {
    box-sizing: border-box;
}

.valuesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #12233f 0%, #1c3a5e 55%, #2a5a4a 100%);
    color: #f4f1e8;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(18, 35, 63, 0.32);
}

.valuesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.valuesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e6c873;
    background: rgba(255, 255, 255, 0.10);
    padding: 5px 14px;
    border-radius: 999px;
}

.valuesim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dfe3ea;
}

.valuesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2a3b54;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.valuesim-period-counter #currentDay,
.valuesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #12233f;
}

.valuesim-round-name {
    background: #d8e0d2;
    color: #2a5a4a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.valuesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a3412;
    background: #f6e3d6;
    padding: 4px 12px;
    border-radius: 999px;
}

.valuesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.valuesim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e0dccd;
    box-shadow: 0 4px 14px rgba(18, 35, 63, 0.06);
    border-top: 4px solid #2a5a4a;
}

.valuesim-card-eva { border-top-color: #1f6b4f; }
.valuesim-card-npv { border-top-color: #2563a8; }
.valuesim-card-liquidity { border-top-color: #b07b16; }
.valuesim-card-governance { border-top-color: #7a4ba8; }

.valuesim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7388;
}

.valuesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #12233f;
}

.valuesim-card-eva .valuesim-value { color: #1f6b4f; }
.valuesim-card-npv .valuesim-value { color: #2563a8; }
.valuesim-card-liquidity .valuesim-value { color: #b07b16; }
.valuesim-card-governance .valuesim-value { color: #7a4ba8; }

.valuesim-sublabel {
    font-size: 0.75rem;
    color: #7c8499;
    line-height: 1.35;
}

.valuesim-value-destroy .valuesim-value { color: #c0392b; }
.valuesim-value-create .valuesim-value { color: #1f6b4f; }

.valuesim-liquidity-breach { border-top-color: #c0392b; }
.valuesim-liquidity-breach .valuesim-value { color: #c0392b; }

.valuesim-covenant-bar {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
    margin-bottom: 14px;
}

.valuesim-covenant-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e0dccd;
    border-left: 4px solid #1c3a5e;
    border-radius: 10px;
    padding: 9px 16px;
    font-weight: 700;
    font-size: 0.92rem;
    color: #12233f;
}

.valuesim-covenant-key {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #6a7388;
}

.valuesim-covenant-item.valuesim-covenant-warn {
    border-left-color: #b07b16;
    background: #fcf4e3;
}

.valuesim-covenant-item.valuesim-covenant-breach {
    border-left-color: #c0392b;
    background: #fbe7e3;
    color: #c0392b;
}

.valuesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #12233f;
    color: #eef1f6;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.valuesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.valuesim-budget-over #budgetDisplay {
    color: #ffb59c;
}

.valuesim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2a5a4a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(18, 35, 63, 0.05);
}

.valuesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.valuesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #12233f;
    margin-bottom: 6px;
}

.valuesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #38415a;
}

.valuesim-briefing-text strong { color: #1f6b4f; }
.valuesim-briefing-text em { color: #9a3412; font-style: italic; }

.valuesim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e0dccd;
    box-shadow: 0 4px 14px rgba(18, 35, 63, 0.06);
}

.valuesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #12233f;
    border-bottom: 2px solid #ece7da;
    padding-bottom: 8px;
}

.valuesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #28344c;
    margin: 14px 0 6px;
}

.valuesim-container select,
.valuesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdc7b6;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #faf8f2;
    color: #1c2230;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.valuesim-container select:focus,
.valuesim-container input[type="number"]:focus {
    outline: none;
    border-color: #2a5a4a;
    box-shadow: 0 0 0 3px rgba(42, 90, 74, 0.15);
}

.valuesim-container select option {
    background-color: #ffffff;
    color: #1c2230;
}

.valuesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2a5a4a;
}

.valuesim-range-readout,
.valuesim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #1c3a5e;
    margin-top: 4px;
}

.valuesim-range-readout span:last-child,
.valuesim-alloc-readout span:nth-child(2) {
    color: #1f6b4f;
    font-weight: 800;
}

.valuesim-hint {
    font-size: 0.8rem;
    color: #7c8499;
    margin-top: 4px;
    line-height: 1.4;
}

.valuesim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.valuesim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6f4ec;
    border: 1px solid #e3ded0;
    border-radius: 9px;
    padding: 8px 12px;
}

.valuesim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #28344c;
}

.valuesim-alloc-row input[type="number"] {
    width: 100px;
    flex: 0 0 100px;
}

.valuesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.valuesim-container .btn-primary {
    background: linear-gradient(135deg, #1f6b4f 0%, #2a5a4a 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(31, 107, 79, 0.28);
}

.valuesim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.valuesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cdc7b6;
    color: #6a7388;
}

.valuesim-coach {
    background: #12233f;
    color: #eef1f6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(18, 35, 63, 0.24);
}

.valuesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e6c873;
    margin-bottom: 8px;
}

.valuesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.valuesim-coach-body strong { color: #f0d488; }
.valuesim-coach-body em { color: #ffb59c; font-style: italic; }

.valuesim-history,
.valuesim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e0dccd;
    box-shadow: 0 4px 14px rgba(18, 35, 63, 0.06);
}

.valuesim-history h3,
.valuesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #12233f;
}

.valuesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #28344c;
}

.valuesim-container table#usfHistoryTable th {
    background: #eef0e9;
    color: #12233f;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ddd9c9;
}

.valuesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0eee4;
}

.valuesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf9f4;
}

.valuesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .valuesim-container {
        padding: 14px;
    }
    .valuesim-header h1 {
        font-size: 1.7rem;
    }
    .valuesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .valuesim-value {
        font-size: 2rem;
    }
    .valuesim-clock {
        margin-left: 0;
    }
    .valuesim-period-counter {
        font-size: 0.88rem;
    }
    .valuesim-covenant-bar {
        grid-template-columns: 1fr;
    }
    .valuesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .valuesim-alloc-row {
        flex-wrap: wrap;
    }
    .valuesim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .valuesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion message (formatCompletionMessage) */
.valuesim-completion { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #12233f; }
.valuesim-cm-head { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; padding-bottom: 14px; border-bottom: 1px solid rgba(18,35,63,0.14); margin-bottom: 16px; }
.valuesim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; color: #1f6b4f; }
.valuesim-cm-score-max { font-size: 18px; font-weight: 600; color: #2a5a4a; margin-left: 2px; }
.valuesim-cm-grade { font-size: 18px; font-weight: 700; color: #12233f; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.valuesim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: .02em; padding: 3px 10px; border-radius: 999px; }
.valuesim-cm-yes { background: rgba(31,107,79,0.15); color: #17553e; }
.valuesim-cm-no { background: rgba(192,57,43,0.12); color: #b03325; }
.valuesim-cm-warn { background: rgba(180,120,20,0.16); color: #8a5c10; }
.valuesim-cm-metrics { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.valuesim-cm-metric { flex: 1 1 120px; background: #eef2ef; border: 1px solid rgba(18,35,63,0.10); border-radius: 10px; padding: 12px 14px; text-align: center; }
.valuesim-cm-mv { display: block; font-size: 22px; font-weight: 800; color: #12233f; }
.valuesim-cm-ml { display: block; font-size: 12px; font-weight: 600; color: #2a5a4a; margin-top: 2px; }
.valuesim-cm-insights-title { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: #2a5a4a; margin-bottom: 8px; }
.valuesim-cm-insights { margin: 0; padding-left: 20px; }
.valuesim-cm-insights li { font-size: 14px; line-height: 1.5; color: #24344c; margin-bottom: 8px; }

