(function() {
    'use strict';

    class ValueAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Create the Value`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (MXN, in MX$ millions unless noted).
            this.WACC = 0.135;               // peso cost of capital
            this.TAX = 0.30;                 // Mexican corporate tax
            this.DEPLOYABLE_CASH = 120;      // hard liquidity gate (MX$M)
            this.LEVERAGE_CAP = 2.5;         // net debt / EBITDA covenant
            this.START_LEVERAGE = 1.2;       // current 720 / 588
            this.COUNCIL_THRESHOLD = 200;    // single-investment approval threshold (MX$M)
            this.DIVIDEND_FLOOR = 180;       // 46-year unbroken streak (MX$M/yr)
            this.EBITDA = 588;               // MX$M
            this.DELISTING_PENALTY = 60;     // chargeback / de-listing (MX$M)
            this.BUYOUT = 900;               // dividend-branch forced buyout (MX$M)

            // Investment economics: capex, incremental annual EBITDA, serves-listing capability.
            this.INVESTMENTS = {
                queretaro:  { capex: 240, dEbitda: 95, servesListing: 1.0 },
                texas:      { capex: 180, dEbitda: 70, servesListing: 0.9 },
                automation: { capex: 90,  dEbitda: 40, servesListing: 0.45 }
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    eva: 0,
                    npv: 0,
                    liquidity: 100,
                    governance: 60,
                    leverage: this.START_LEVERAGE,
                    dividend: this.DIVIDEND_FLOOR,
                    cashUsed: 0,
                    covenantBreach: false,
                    cashShort: false,
                    buyoutTriggered: false,
                    valueDestroyed: false,
                    investment: ``,
                    evaHistory: [0],
                    npvHistory: [0],
                    liquidityHistory: [100],
                    governanceHistory: [60],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    gate: `liquidity`,
                    bind: `both`,
                    candor: 70,
                    invest: `queretaro`,
                    lever: `growth`,
                    serve: 80,
                    loan: 120,
                    placement: 0,
                    leaseback: 0,
                    dividend: `preserve`,
                    control: 70,
                    caseframe: `evagovernance`,
                    branch: `reinvest`,
                    defend: 70,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const gate = document.getElementById(`gateInput`);
                const bind = document.getElementById(`bindInput`);
                const candor = document.getElementById(`candorInput`);
                if (gate) decisions.gate = gate.value;
                if (bind) decisions.bind = bind.value;
                if (candor) decisions.candor = parseInt(candor.value, 10);
                if (!Number.isFinite(decisions.candor) || decisions.candor < 0 || decisions.candor > 100) {
                    warn(`warn_candor_range`); return false;
                }
            } else if (round === 2) {
                const inv = document.getElementById(`investInput`);
                const lev = document.getElementById(`leverInput`);
                const serve = document.getElementById(`serveInput`);
                if (inv) decisions.invest = inv.value;
                if (lev) decisions.lever = lev.value;
                if (serve) decisions.serve = parseInt(serve.value, 10);
                if (!Number.isFinite(decisions.serve) || decisions.serve < 0 || decisions.serve > 100) {
                    warn(`warn_serve_range`); return false;
                }
            } else if (round === 3) {
                const loan = document.getElementById(`loanInput`);
                const plac = document.getElementById(`placementInput`);
                const lb = document.getElementById(`leasebackInput`);
                const div = document.getElementById(`dividendInput`);
                const ctrl = document.getElementById(`controlInput`);
                if (loan) decisions.loan = parseFloat(loan.value);
                if (plac) decisions.placement = parseFloat(plac.value);
                if (lb) decisions.leaseback = parseFloat(lb.value);
                if (div) decisions.dividend = div.value;
                if (ctrl) decisions.control = parseInt(ctrl.value, 10);
                const sources = [decisions.loan, decisions.placement, decisions.leaseback];
                if (sources.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_funding_negative`); return false;
                }
                if (decisions.leaseback > 200) {
                    warn(`warn_leaseback_cap`); return false;
                }
                if (!Number.isFinite(decisions.control) || decisions.control < 0 || decisions.control > 100) {
                    warn(`warn_control_range`); return false;
                }
            } else if (round === 4) {
                const cs = document.getElementById(`caseInput`);
                const br = document.getElementById(`branchInput`);
                const df = document.getElementById(`defendInput`);
                const cv = document.getElementById(`convictionInput`);
                if (cs) decisions.caseframe = cs.value;
                if (br) decisions.branch = br.value;
                if (df) decisions.defend = parseInt(df.value, 10);
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.defend) || decisions.defend < 0 || decisions.defend > 100) {
                    warn(`warn_defend_range`); return false;
                }
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let evaDelta = 0, npvDelta = 0, liquidityDelta = 0, governanceDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose value and liquidity. Liquidity is the hard gate (KEY CONCEPT:
                // liquidity vs profitability). Mis-framing the gate forfeits the discipline.
                if (d.gate === `liquidity`) {
                    governanceDelta += 6; liquidityDelta += 6; coachKey = `coach_r1_gate_right`;
                } else if (d.gate === `ebitda`) {
                    governanceDelta -= 6; liquidityDelta -= 6; coachKey = `coach_r1_gate_ebitda`;
                } else if (d.gate === `market`) {
                    governanceDelta -= 2; liquidityDelta -= 4; coachKey = `coach_r1_gate_market`;
                } else {
                    governanceDelta -= 10; liquidityDelta -= 8; coachKey = `coach_r1_gate_none`;
                }

                // Which constraint binds: both the 2.5x covenant and the MX$180M dividend
                // hold together (Three-Circle model: family, ownership, business collide).
                if (d.bind === `both`) {
                    governanceDelta += 6;
                    if (d.gate === `liquidity`) coachKey = `coach_r1_diag_sharp`;
                } else if (d.bind === `covenant` || d.bind === `dividend`) {
                    governanceDelta += 1; coachKey = `coach_r1_bind_partial`;
                } else {
                    governanceDelta -= 10; liquidityDelta -= 4; coachKey = `coach_r1_bind_none`;
                }

                // Candid baseline of cash gate and covenant headroom.
                if (d.candor >= 60) { governanceDelta += 4; }
                else if (d.candor <= 25) { governanceDelta -= 8; coachKey = `coach_r1_lowcandor`; }

                summaryKey = (d.gate === `liquidity` && d.bind === `both`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose the investment + value-creation lever; size capacity for the listing.
                const inv = this.INVESTMENTS[d.invest] || this.INVESTMENTS.queretaro;
                ds.investment = d.invest;

                // EVA discipline (KEY CONCEPT): NOPAT (after-tax incremental EBITDA, rough)
                // minus the capital charge (capex * WACC). This is the spine of the scorecard.
                const nopat = inv.dEbitda * (1 - this.TAX);
                const capitalCharge = inv.capex * this.WACC;
                const investEva = nopat - capitalCharge;     // queretaro ~+34, texas ~+25, automation ~+16
                evaDelta += investEva;

                // NPV proxy: 3-yr FCF (after-tax EBITDA, lightly discounted) less capex.
                const annualFcf = inv.dEbitda * (1 - this.TAX);
                const investNpv = annualFcf * 2.32 - inv.capex * 0.62; // ~queretaro +40, automation +14
                npvDelta += investNpv;

                // Strategic-fit / lever interaction with the U.S. listing.
                const growthFit = d.lever === `growth`;
                if (growthFit && (d.invest === `queretaro` || d.invest === `texas`)) {
                    npvDelta += 14; evaDelta += 5; governanceDelta += 4; coachKey = `coach_r2_growthfit`;
                } else if (d.lever === `margin`) {
                    evaDelta += 4; coachKey = `coach_r2_margin`;
                } else if (d.lever === `assetturn`) {
                    liquidityDelta += 8; coachKey = `coach_r2_assetturn`;
                }

                // Serving the won listing. Under-serving an invest that can serve it triggers
                // the MX$60M chargeback/de-listing penalty (Common Error 5).
                const canServe = inv.servesListing;          // capability ceiling of the asset
                const effectiveServe = Math.min(d.serve / 100, canServe);
                if (effectiveServe >= 0.85) {
                    npvDelta += 18; evaDelta += 4; coachKey = `coach_r2_served`;
                } else if (effectiveServe >= 0.6) {
                    npvDelta += 6;
                } else {
                    // Under-served a won opportunity: chargeback hits NPV and drains liquidity.
                    npvDelta -= this.DELISTING_PENALTY * 0.5; liquidityDelta -= 14;
                    ds.valueDestroyed = true; coachKey = `coach_r2_underserve`;
                }

                // The automation play simply cannot serve the listing — name the trade.
                if (d.invest === `automation` && d.lever === `growth`) {
                    npvDelta -= 10; coachKey = `coach_r2_toosmall`;
                }

                summaryKey = (investEva > 20 && effectiveServe >= 0.85) ? `sum_r2_good`
                    : (effectiveServe < 0.6 ? `sum_r2_underserve` : `sum_r2_weak`);
            } else if (round === 3) {
                // Structure the financing within the family compact (Common Errors 2 & 3).
                const inv = this.INVESTMENTS[ds.investment] || this.INVESTMENTS.queretaro;
                const need = Math.max(0, inv.capex - this.DEPLOYABLE_CASH);  // beyond the MX$120M cash
                const external = d.loan + d.placement + d.leaseback;
                ds.cashUsed = this.DEPLOYABLE_CASH;

                // Funding sufficiency: a credible dividend cut also contributes funding.
                let dividendFunding = 0;
                if (d.dividend === `engage`) dividendFunding = 90;   // a time-bound, agreed cut
                else if (d.dividend === `cut`) dividendFunding = 120; // a deep unilateral cut

                const totalRaised = external + dividendFunding;
                if (totalRaised < need - 1) {
                    // Under-funded: the investment cannot actually be paid for (Decision Tree 1).
                    ds.cashShort = true; liquidityDelta -= 18; npvDelta -= 12; governanceDelta -= 6;
                    coachKey = `coach_r3_shortfall`;
                } else {
                    liquidityDelta += 6;
                }

                // Term loan raises leverage. Pro-forma leverage = (720 + loan) / 588.
                ds.leverage = Math.round(((720 + d.loan) / this.EBITDA) * 100) / 100;
                if (ds.leverage > this.LEVERAGE_CAP + 0.001) {
                    ds.covenantBreach = true; liquidityDelta -= 16; governanceDelta -= 10; evaDelta -= 6;
                    coachKey = `coach_r3_breach`;
                } else if (ds.leverage >= 2.35) {
                    // Spent almost the entire covenant cushion (Common Error 2 / Decision Tree 2).
                    liquidityDelta -= 8; governanceDelta -= 4; coachKey = `coach_r3_nocushion`;
                } else if (d.loan > 0 && ds.leverage <= 2.2) {
                    // Debt used but headroom preserved — headroom is itself an asset.
                    liquidityDelta += 4; governanceDelta += 4;
                }

                // Source-mix governance: placement dilutes the family (control preference);
                // leaseback frees cash but loses an owned asset.
                if (d.placement >= 60) {
                    if (d.control >= 60) { governanceDelta -= 14; coachKey = `coach_r3_dilute`; }
                    else { governanceDelta -= 20; coachKey = `coach_r3_dilute`; }
                } else if (d.leaseback >= 60) {
                    governanceDelta -= 2; evaDelta += 2;  // pragmatic, modest asset loss
                }

                // Dividend decision (Decision Tree 3 + dividend-as-governance).
                if (d.dividend === `preserve`) {
                    ds.dividend = this.DIVIDEND_FLOOR; governanceDelta += 8;
                    if (ds.leverage <= 2.2 && !ds.cashShort) coachKey = `coach_r3_preserve`;
                } else if (d.dividend === `engage`) {
                    ds.dividend = 130; governanceDelta += 4; evaDelta += 4; coachKey = `coach_r3_engage`;
                } else if (d.dividend === `cut`) {
                    ds.dividend = 60; governanceDelta -= 18; liquidityDelta -= 6;
                    ds.buyoutTriggered = true; coachKey = `coach_r3_unilateral`;
                }

                // Weight on family control vs cheapest capital.
                if (d.control >= 60 && d.placement < 60) { governanceDelta += 6; }
                else if (d.control <= 25 && d.placement >= 60) { governanceDelta -= 4; }

                summaryKey = (!ds.cashShort && !ds.covenantBreach && ds.leverage <= 2.2 && d.dividend !== `cut`)
                    ? `sum_r3_good`
                    : (ds.covenantBreach || d.dividend === `cut` ? `sum_r3_risk` : `sum_r3_weak`);
            } else if (round === 4) {
                // Win the Council vote (Common Error 4 + approvable-value lesson).
                // Council-approval threshold: a >MX$200M single investment needs Council consent;
                // arriving without value-and-governance framing reads as bypassing them.
                const inv = this.INVESTMENTS[ds.investment] || this.INVESTMENTS.queretaro;
                const aboveThreshold = inv.capex > this.COUNCIL_THRESHOLD;

                switch (d.caseframe) {
                    case `evagovernance`: evaDelta += 6; governanceDelta += 8; coachKey = `coach_r4_evagov`; break;
                    case `ebitdaonly`: evaDelta -= 8; governanceDelta -= 4; ds.valueDestroyed = true; coachKey = `coach_r4_ebitdaonly`; break;
                    case `speed`: governanceDelta -= 10; coachKey = `coach_r4_speed`; break;
                }

                // Addressing the dividend-dependent branch's income question.
                switch (d.branch) {
                    case `reinvest`: governanceDelta += 10; coachKey = (d.caseframe === `evagovernance`) ? `coach_r4_reinvest` : coachKey; break;
                    case `ignore`: governanceDelta -= 10; coachKey = `coach_r4_ignore`; break;
                    case `overrule`:
                        governanceDelta -= 16; liquidityDelta -= 10; ds.buyoutTriggered = true; coachKey = `coach_r4_overrule`; break;
                }

                // Defending covenant headroom as an asset.
                if (d.defend >= 60) { governanceDelta += 5; liquidityDelta += 4; }
                else if (d.defend <= 25) { governanceDelta -= 4; }

                // If the investment is above the Council threshold, a strong governance case
                // matters even more; a weak one is penalised harder.
                if (aboveThreshold) {
                    if (d.caseframe === `evagovernance` && d.branch === `reinvest`) governanceDelta += 4;
                    else governanceDelta -= 4;
                }

                // Conviction in approvable value.
                governanceDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.caseframe === `evagovernance` && d.branch === `reinvest`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Forced buyout drains liquidity sharply (Decision Tree 3).
            if (ds.buyoutTriggered) { liquidityDelta -= 6; }

            // Apply deltas with headroom-preserving clamps.
            ds.eva = Math.round((ds.eva + evaDelta) * 10) / 10;
            ds.npv = Math.round((ds.npv + npvDelta) * 10) / 10;
            ds.liquidity = Math.max(0, Math.min(120, Math.round(ds.liquidity + liquidityDelta)));
            ds.governance = Math.max(0, Math.min(100, Math.round(ds.governance + governanceDelta)));

            // Flag value destruction: EBITDA-style growth that loses money after the capital charge.
            if (ds.eva < 0) ds.valueDestroyed = true;

            ds.evaHistory.push(ds.eva);
            ds.npvHistory.push(ds.npv);
            ds.liquidityHistory.push(ds.liquidity);
            ds.governanceHistory.push(ds.governance);

            // v1.1.0: publish composite to the reporting/grading layer every period.
            ds.performance = { overallScore: this._composite(ds) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                eva: ds.eva,
                evaDelta: Math.round(evaDelta * 10) / 10,
                npv: ds.npv,
                npvDelta: Math.round(npvDelta * 10) / 10,
                liquidity: ds.liquidity,
                governance: ds.governance,
                leverage: ds.leverage,
                covenantBreach: ds.covenantBreach,
                buyoutTriggered: ds.buyoutTriggered,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`evaDisplay`, `domainState.eva`, (v) => {
                const card = document.querySelector(`.valuesim-card-eva`);
                if (card) {
                    card.classList.toggle(`valuesim-value-create`, Number(v) > 0);
                    card.classList.toggle(`valuesim-value-destroy`, Number(v) < 0);
                }
                return this._money(v);
            });
            uiManager.bind(`npvDisplay`, `domainState.npv`, (v) => {
                const card = document.querySelector(`.valuesim-card-npv`);
                if (card) {
                    card.classList.toggle(`valuesim-value-create`, Number(v) > 0);
                    card.classList.toggle(`valuesim-value-destroy`, Number(v) < 0);
                }
                return this._money(v);
            });
            uiManager.bind(`liquidityDisplay`, `domainState.liquidity`, (v) => {
                const card = document.querySelector(`.valuesim-card-liquidity`);
                if (card) card.classList.toggle(`valuesim-liquidity-breach`, Number(v) < 40);
                return Math.round(Number(v));
            });
            uiManager.bind(`governanceDisplay`, `domainState.governance`, (v) => Math.round(Number(v)));

            uiManager.bind(`leverageDisplay`, `domainState.leverage`, (v) => {
                const item = document.querySelector(`.valuesim-covenant-bar .valuesim-covenant-item:first-child`);
                if (item) {
                    const breach = Number(v) > this.LEVERAGE_CAP + 0.001;
                    const warn = !breach && Number(v) >= 2.35;
                    item.classList.toggle(`valuesim-covenant-breach`, breach);
                    item.classList.toggle(`valuesim-covenant-warn`, warn);
                }
                return Number(v).toFixed(1) + `x / 2.5x`;
            });
            uiManager.bind(`dividendDisplay`, `domainState.dividend`, (v) => {
                const item = document.querySelector(`.valuesim-covenant-bar .valuesim-covenant-item:last-child`);
                if (item) item.classList.toggle(`valuesim-covenant-breach`, Number(v) < this.DIVIDEND_FLOOR);
                return `MX$` + Math.round(Number(v)) + `M`;
            });
            uiManager.bind(`budgetDisplay`, `domainState.cashUsed`, (v) => {
                const bar = document.querySelector(`.valuesim-budget-bar`);
                if (bar) bar.classList.toggle(`valuesim-budget-over`, Number(v) > this.DEPLOYABLE_CASH + 0.001);
                return `MX$` + Math.round(Number(v)) + `M / MX$120M`;
            });

            const self = this;

            // Slider readouts.
            const sliderPairs = [
                [`candorInput`, `candorReadout`],
                [`serveInput`, `serveReadout`],
                [`controlInput`, `controlReadout`],
                [`defendInput`, `defendReadout`]
            ];
            sliderPairs.forEach(function(pair) {
                const inp = document.getElementById(pair[0]);
                const out = document.getElementById(pair[1]);
                if (inp && out) {
                    out.textContent = inp.value;
                    inp.addEventListener(`input`, function() { out.textContent = inp.value; });
                }
            });

            // Live funding total + need readout.
            const fundIds = [`loanInput`, `placementInput`, `leasebackInput`];
            const fundingReadout = document.getElementById(`fundingReadout`);
            const needReadout = document.getElementById(`needReadout`);
            const recompute = function() {
                let total = 0;
                fundIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                if (fundingReadout) fundingReadout.textContent = Math.round(total);
                const ds = window.mySimulation.state.domainState;
                const inv = self.INVESTMENTS[ds.investment] || self.INVESTMENTS.queretaro;
                const need = Math.max(0, inv.capex - self.DEPLOYABLE_CASH);
                if (needReadout) needReadout.textContent = need;
                const bar = document.querySelector(`.valuesim-alloc-readout`);
                if (bar) bar.style.color = (total < need - 1) ? `#c0392b` : ``;
            };
            fundIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        _money(v) {
            const n = Math.round(Number(v) * 10) / 10;
            const sign = n < 0 ? `−` : ``;
            return sign + `MX$` + Math.abs(n) + `M`;
        }

        getChartConfig() {
            return {
