                                ticks: { color: `#6a7388` }, grid: { color: `rgba(18,35,63,0.08)` },
                                title: { display: true, text: `MX$M`, color: `#6a7388` }
                            },
                            yIndex: {
                                position: `right`, beginAtZero: true, max: 120,
                                ticks: { color: `#6a7388` }, grid: { drawOnChartArea: false },
                                title: { display: true, text: `0–120`, color: `#6a7388` }
                            },
                            x: {
                                ticks: { color: `#6a7388` }, grid: { color: `rgba(18,35,63,0.06)` },
                                title: { display: true, text: `Round`, color: `#6a7388` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.evaHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                valueChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.evaHistory },
                        { data: ds.npvHistory },
                        { data: ds.liquidityHistory },
                        { data: ds.governanceHistory }
                    ]
                }
            };
        }

        // Shared composite. Written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary
        // (may exceed 100 when liquidity>100 by the sim's original design; preserved for stability).
        _composite(ds) {
            var eva = ds.eva || 0;
            var npv = ds.npv || 0;
            var liquidity = ds.liquidity || 0;
            var governance = ds.governance || 0;
            return Math.round(
                Math.max(0, Math.min(100, eva * 1.2 + 40)) * 0.30 +
                Math.max(0, Math.min(100, npv * 0.9 + 40)) * 0.25 +
                liquidity * 0.20 +
                governance * 0.25
            );
        }

        _cl(key, fallback) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) {}
            return fallback;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const eva = ds.eva;
            const npv = ds.npv;
            const liquidity = ds.liquidity;
            const governance = ds.governance;

            const createsValue = eva > 0 && npv > 0;
            const covenantOk = !ds.covenantBreach && ds.leverage <= this.LEVERAGE_CAP + 0.001;
            const solvent = liquidity >= 50 && !ds.cashShort;
            const approvable = governance >= 60 && !ds.buyoutTriggered;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            let performanceKey = `grade_destroyed`;
            if (createsValue && covenantOk && solvent && approvable && composite >= 72) performanceKey = `grade_created`;
            else if (createsValue && approvable && covenantOk) performanceKey = `grade_approvable`;
            else if (createsValue && !approvable) performanceKey = `grade_unapprovable`;
            else if (createsValue && !solvent) performanceKey = `grade_illiquid`;
            else if (eva > 0 || npv > 0) performanceKey = `grade_thin`;
            const performance = T(performanceKey);

            const insights = [];
            if (createsValue && covenantOk && solvent && approvable) insights.push(window.mySimulation.t(`insight_created`));
            else if (createsValue && !approvable) insights.push(window.mySimulation.t(`insight_unapprovable`));
            else if (createsValue && !solvent) insights.push(window.mySimulation.t(`insight_illiquid`));
            else if (eva <= 0) insights.push(window.mySimulation.t(`insight_destroyed`));
            else insights.push(window.mySimulation.t(`insight_thin`));

            if (ds.covenantBreach) insights.push(window.mySimulation.t(`insight_breach`));
            if (ds.buyoutTriggered) insights.push(window.mySimulation.t(`insight_buyout`));
            if (ds.cashShort) insights.push(window.mySimulation.t(`insight_cashshort`));
            if (createsValue && approvable && solvent && covenantOk) insights.push(window.mySimulation.t(`insight_balanced`));

            return {
                eva: eva,
                npv: npv,
                liquidity: liquidity,
                governance: governance,
                createsValue: createsValue,
                approvable: approvable,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                covenantBreach: ds.covenantBreach,
                buyoutTriggered: ds.buyoutTriggered,
                valueOk: (createsValue && covenantOk && solvent && approvable),
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var self = this;
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var money = function(v) { try { return self._money(v); } catch (e) { return String(Math.round((v || 0) * 10) / 10); } };
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var ok = !!s.valueOk;
            var badge = ok
                ? '<span class="valuesim-cm-badge valuesim-cm-yes">' + T('cm_met') + '</span>'
                : '<span class="valuesim-cm-badge valuesim-cm-no">' + T('cm_missed') + '</span>';
            var breachBadge = s.covenantBreach
                ? '<span class="valuesim-cm-badge valuesim-cm-warn">' + T('cm_breach_badge') + '</span>'
                : '';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="valuesim-cm-metric"><span class="valuesim-cm-mv">' + money(s.eva) + '</span><span class="valuesim-cm-ml">' + T('cm_m_eva') + '</span></div>'
                + '<div class="valuesim-cm-metric"><span class="valuesim-cm-mv">' + money(s.npv) + '</span><span class="valuesim-cm-ml">' + T('cm_m_npv') + '</span></div>'
                + '<div class="valuesim-cm-metric"><span class="valuesim-cm-mv">' + Math.round(s.liquidity || 0) + '</span><span class="valuesim-cm-ml">' + T('cm_m_liquidity') + '</span></div>'
                + '<div class="valuesim-cm-metric"><span class="valuesim-cm-mv">' + Math.round(s.governance || 0) + '</span><span class="valuesim-cm-ml">' + T('cm_m_governance') + '</span></div>';
            return ''
                + '<div class="valuesim-completion">'
                +   '<div class="valuesim-cm-head">'
                +     '<div class="valuesim-cm-score">' + score + '<span class="valuesim-cm-score-max">/100</span></div>'
                +     '<div class="valuesim-cm-grade">' + grade + ' ' + badge + breachBadge + '</div>'
                +   '</div>'
                +   '<div class="valuesim-cm-metrics">' + metrics + '</div>'
                +   '<div class="valuesim-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="valuesim-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.covenantBreach) return window.mySimulation.t(`hint_breach`);
            if (ds.buyoutTriggered) return window.mySimulation.t(`hint_buyout`);
            if (ds.cashShort) return window.mySimulation.t(`hint_cashshort`);
            if (ds.eva < 0) return window.mySimulation.t(`hint_eva`);
            if (state.currentPeriod >= 3 && ds.governance < 45) return window.mySimulation.t(`hint_governance`);
            if (ds.eva > 0 && ds.npv > 0 && ds.governance >= 60 && ds.liquidity >= 50) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.eva`, label: `EVA`, i18nKey: `col_eva`, formatter: (v) => this._money(v) },
                { key: `results.npv`, label: `NPV`, i18nKey: `col_npv`, formatter: (v) => this._money(v) },
                { key: `results.governance`, label: `Gov. Fit`, i18nKey: `col_governance`, formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
